<template><ContentWrap><el-form inline><el-form-item label="Scope"><el-select v-model="q.scope" clearable><el-option v-for="x in scopes" :key="x" :value="x" :label="x"/></el-select></el-form-item><el-form-item label="类型"><el-input v-model="q.memoryType" clearable/></el-form-item><el-form-item label="成员"><el-input v-model="q.memberId" clearable/></el-form-item><el-form-item label="机器人"><el-input v-model="q.robotId" clearable/></el-form-item><el-form-item label="状态"><el-input v-model="q.status" clearable/></el-form-item></el-form><el-table :data="filtered"><el-table-column prop="scope" label="Scope"/><el-table-column prop="memoryType" label="类型"/><el-table-column label="成员"><template #default="{row}">{{row.memberId?`成员 #${row.memberId}`:'-'}}</template></el-table-column><el-table-column label="机器人"><template #default="{row}">{{robotName(row.robotId)}}</template></el-table-column><el-table-column prop="content" label="内容"/><el-table-column prop="expiresAt" label="过期时间"/><el-table-column prop="status" label="状态"/><el-table-column label="来源"><template #default="{row}"><router-link v-if="row.sourceConversationId" :to="`/ai/conversation?id=${row.sourceConversationId}`">#{{row.sourceConversationId}}</router-link></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">失效</el-button></template></el-table-column></el-table><el-dialog v-model="open" title="编辑记忆"><el-input v-model="form.content" type="textarea"/><el-input v-model="form.summary" placeholder="摘要"/><el-input-number v-model="form.importance" :min="0" :max="1" :step=".1"/><el-date-picker v-model="form.expiresAt" type="datetime"/><el-button @click="save">保存</el-button></el-dialog></ContentWrap></template><script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{AiMemoryApi,type MemoryVO}from'@/api/ai/memory';import{RobotApi,type RobotVO}from'@/api/robot/robot';const rows=ref<MemoryVO[]>([]),robots=ref<RobotVO[]>([]),open=ref(false),editing=ref<number>(),q=reactive<any>({}),form=reactive<any>({}),scopes=['MEMBER','MEMBER_ROBOT','ROBOT'];const filtered=computed(()=>rows.value.filter(x=>(!q.scope||x.scope===q.scope)&&(!q.memoryType||x.memoryType.includes(q.memoryType))&&(!q.memberId||String(x.memberId)===q.memberId)&&(!q.robotId||String(x.robotId)===q.robotId)&&(!q.status||x.status===q.status)));function robotName(id?:number){return robots.value.find(x=>x.id===id)?.name||(id?`#${id}`:'-')}async function load(){rows.value=await AiMemoryApi.list();const r:any=await RobotApi.page({pageNo:1,pageSize:100});robots.value=r.list||r||[]}function edit(r:MemoryVO){editing.value=r.id;Object.assign(form,r);open.value=true}async function save(){if(editing.value)await AiMemoryApi.update(editing.value,form);open.value=false;await load()}async function remove(r:MemoryVO){await AiMemoryApi.delete(r.id);await load()}onMounted(load)</script>